<?php
/**
 * The wording of the dues-invoice email.
 *
 * Staff can replace three pieces of it in Settings → Dues & Billing — the
 * SUBJECT, the INTRO (greeting + the "your invoice totals $X" sentence) and
 * the CLOSING (the sign-off) — using merge tags such as {firm}, {year} and
 * {total}. Everything else is generated by the system and cannot be edited
 * away: the list of who the invoice covers and what each is charged, the
 * payment link, and the mail-a-check address. A blank field means "use the
 * built-in wording", which is exactly what the email said before this
 * existed.
 *
 * This class is PURE (no WordPress): build() assembles the message from plain
 * values, so the wording rules — and that the built-in text is byte-for-byte
 * unchanged — are unit-tested (tests/InvoiceEmailTest.php).
 * MyNJILGA_Invoice_Sender::compose() gathers the values and calls it.
 */
class MyNJILGA_Invoice_Email {

    /** Settings key for each editable piece. */
    const FIELDS = [
        'subject' => 'email_subject',
        'heading' => 'email_heading',
        'intro'   => 'email_intro',
        'closing' => 'email_closing',
        'button'  => 'email_button',
    ];

    /** The one-line pieces (no line breaks, length of a subject). */
    const ONE_LINE = [ 'subject', 'heading', 'button' ];

    /** The HTML email's colours: NJILGA navy, and the summary card's grey. */
    const COLOR_ACCENT = '#1d2b4f';
    const COLOR_TEXT   = '#1f2937';
    const COLOR_MUTED  = '#6b7280';
    const COLOR_CARD   = '#f5f6f8';
    const COLOR_LINE   = '#e5e7eb';

    /** The image across the top of the HTML email when none is set on the Invoice Email tab. */
    const DEFAULT_HEADER_IMAGE = 'https://njilga.org/wp-content/uploads/2026/06/fallback_image_njilga.png';

    /** Merge tag => what it becomes. */
    const TAGS = [
        'firm'       => 'The firm\'s name (or "your firm" if there isn\'t one)',
        'year'       => 'The dues year, e.g. 2027',
        'total'      => 'The invoice total, e.g. $325.00',
        'name'       => 'The bill-to contact\'s full name',
        'first_name' => 'The bill-to contact\'s first name',
        'invoice'    => 'What the invoice is: "membership dues invoice", or the assessment\'s name followed by "invoice"',
    ];

    const MAX_SUBJECT = 200;
    const MAX_TEXT    = 2000;

    /** The pay-link line. Always present: custom wording cannot remove it. */
    const PAY_LINE = 'Pay online here: ';

    /** Shown in a preview of an invoice that has not been created yet. */
    const PLACEHOLDER_LINK = '[the payment link appears here once the invoice is created]';

    /** Put on the subject of an invoice that replaces an earlier one. */
    const UPDATED_PREFIX = 'Updated Invoice: ';

    /** Put on the subject of an invoice emailed again as a reminder that it is unpaid. */
    const REMINDER_PREFIX = 'Reminder: ';

    // -------------------------------------------------------------------------
    // An invoice that replaces an earlier one
    // -------------------------------------------------------------------------

    /**
     * The two sentences an UPDATED invoice carries (null when it replaces
     * nothing). Not editable wording: a firm holding two invoices for the same
     * year must be told, in the email itself, which one to pay — so like the
     * list of who the invoice covers, custom wording can't remove it.
     *
     * Input: 'replaces' => [ 'number' => the old invoice's number ('' = unknown), 'total' => its total, formatted ('' = unknown) ].
     *
     * @param array<string,mixed> $in build()'s input
     * @return array{lead:string,rest:string}|null
     */
    public static function updated_parts( array $in ): ?array {
        $r = $in['replaces'] ?? null;
        if ( ! is_array( $r ) || ! $r ) {
            return null;
        }
        $number = trim( (string) ( $r['number'] ?? '' ) );
        $total  = trim( (string) ( $r['total'] ?? '' ) );
        $was    = $number !== '' ? 'invoice ' . $number : 'the invoice we sent you earlier';
        if ( $total !== '' ) {
            $was .= ' (' . $total . ')';
        }
        return [
            'lead' => 'This is an updated invoice.',
            'rest' => 'It replaces ' . $was . ', which has been voided. Please disregard the earlier invoice and its payment link, and pay this one.',
        ];
    }

    /** The notice as one plain-text paragraph ('' when the invoice replaces nothing). @param array<string,mixed> $in */
    public static function updated_notice( array $in ): string {
        $p = self::updated_parts( $in );
        return $p === null ? '' : $p['lead'] . ' ' . $p['rest'];
    }

    /** The subject, marked as an update (once) when the invoice replaces an earlier one. @param array<string,mixed> $in */
    public static function updated_subject( string $subject, array $in ): string {
        if ( self::updated_parts( $in ) === null || stripos( ltrim( $subject ), 'updated' ) === 0 ) {
            return $subject;
        }
        return self::UPDATED_PREFIX . $subject;
    }

    // -------------------------------------------------------------------------
    // An invoice emailed again as a reminder
    // -------------------------------------------------------------------------

    /**
     * The two sentences a REMINDER carries (null when this is not a reminder). Like the updated
     * notice they are not editable wording: a firm must be told, in the email itself, that this is
     * a reminder about an invoice it already has.
     *
     * Input: 'reminder' => [ 'number' => the invoice's number ('' = unknown), 'total' => its total, formatted ('' = unknown) ].
     *
     * @param array<string,mixed> $in build()'s input
     * @return array{lead:string,rest:string}|null
     */
    public static function reminder_parts( array $in ): ?array {
        $r = $in['reminder'] ?? null;
        if ( ! is_array( $r ) || ! $r ) {
            return null;
        }
        $number = trim( (string) ( $r['number'] ?? '' ) );
        $total  = trim( (string) ( $r['total'] ?? '' ) );
        $which  = $number !== '' ? 'invoice ' . $number : 'this invoice';
        if ( $total !== '' ) {
            $which .= ' (' . $total . ')';
        }
        return [
            'lead' => 'This is a friendly reminder.',
            'rest' => 'Our records show that ' . $which . ' has not been paid yet. If you have already paid it, thank you — please disregard this message.',
        ];
    }

    /** The reminder notice as one plain-text paragraph ('' when this is not a reminder). @param array<string,mixed> $in */
    public static function reminder_notice( array $in ): string {
        $p = self::reminder_parts( $in );
        return $p === null ? '' : $p['lead'] . ' ' . $p['rest'];
    }

    /**
     * The subject as it goes out: marked "Reminder:" for a reminder, else "Updated Invoice:" for an
     * invoice that replaces an earlier one (a reminder of an updated invoice is a reminder first —
     * the body still says it replaces the earlier one). Never marked twice.
     *
     * @param array<string,mixed> $in
     */
    public static function marked_subject( string $subject, array $in ): string {
        if ( self::reminder_parts( $in ) !== null ) {
            return stripos( ltrim( $subject ), 'reminder' ) === 0 ? $subject : self::REMINDER_PREFIX . $subject;
        }
        return self::updated_subject( $subject, $in );
    }

    // -------------------------------------------------------------------------
    // The built-in wording, as templates (shown as the field placeholders)
    // -------------------------------------------------------------------------

    public static function default_template( string $field ): string {
        switch ( $field ) {
            case 'subject':
                return '{year} NJILGA Membership Dues Invoice — {firm}';
            case 'intro':
                return "Hi {name},\n\n{firm}'s {year} NJILGA {invoice} totals {total}.";
            case 'closing':
                return "Thank you,\nNJILGA";
            case 'heading':
                return 'NJILGA Membership Dues – Action Required';
            case 'button':
                return 'Pay My Dues Online';
        }
        return '';
    }

    // -------------------------------------------------------------------------
    // Cleaning what staff type
    // -------------------------------------------------------------------------

    /**
     * Normalise a piece of wording for storage: plain text only, bounded,
     * no control characters; a subject is one line.
     */
    public static function clean( string $field, string $raw ): string {
        $s = str_replace( [ "\r\n", "\r" ], "\n", $raw );
        $s = strip_tags( $s );
        $s = (string) preg_replace( '/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/', '', $s );
        if ( in_array( $field, self::ONE_LINE, true ) ) {
            $s = trim( (string) preg_replace( '/\s+/', ' ', $s ) );
            return self::cut( $s, self::MAX_SUBJECT );
        }
        $s = trim( (string) preg_replace( "/\n{3,}/", "\n\n", $s ) );
        return self::cut( $s, self::MAX_TEXT );
    }

    private static function cut( string $s, int $max ): string {
        return function_exists( 'mb_substr' ) ? mb_substr( $s, 0, $max ) : substr( $s, 0, $max );
    }

    /**
     * Merge tags in $text that aren't ones we know — a typo like {frim} would
     * otherwise be emailed to a firm as literal text.
     *
     * @return array<int,string> The unknown tag names (lower-cased, de-duplicated).
     */
    public static function unknown_tags( string $text ): array {
        if ( ! preg_match_all( '/\{([A-Za-z0-9_]+)\}/', $text, $m ) ) {
            return [];
        }
        $unknown = [];
        foreach ( $m[1] as $tag ) {
            $tag = strtolower( $tag );
            if ( ! isset( self::TAGS[ $tag ] ) ) {
                $unknown[ $tag ] = $tag;
            }
        }
        return array_values( $unknown );
    }

    // -------------------------------------------------------------------------
    // Rendering
    // -------------------------------------------------------------------------

    /**
     * Replace {tags} with their values. A tag that isn't known is left exactly
     * as written.
     *
     * @param array<string,string> $vars tag => value
     */
    public static function render( string $template, array $vars ): string {
        return (string) preg_replace_callback(
            '/\{([A-Za-z0-9_]+)\}/',
            static function ( array $m ) use ( $vars ) {
                $tag = strtolower( $m[1] );
                return array_key_exists( $tag, $vars ) ? (string) $vars[ $tag ] : $m[0];
            },
            $template
        );
    }

    /**
     * The values behind the merge tags.
     *
     * @param array<string,mixed> $in build()'s input.
     * @return array<string,string>
     */
    public static function vars( array $in ): array {
        $firm  = trim( (string) ( $in['firm'] ?? '' ) );
        $label = trim( (string) ( $in['assessment_label'] ?? '' ) );
        $name  = trim( (string) ( $in['name'] ?? '' ) );
        // A contact with only a full name on file still gets a greeting: the first word of it.
        $first = trim( (string) ( $in['first_name'] ?? '' ) );
        if ( $first === '' && $name !== '' ) {
            $first = (string) preg_split( '/\s+/', $name )[0];
        }
        return [
            'firm'       => $firm !== '' ? $firm : 'your firm',
            'year'       => (string) (int) ( $in['year'] ?? 0 ),
            'total'      => (string) ( $in['total'] ?? '' ),
            'name'       => $name,
            'first_name' => $first,
            'invoice'    => ! empty( $in['is_assessment'] )
                ? ( $label !== '' ? $label : 'assessment' ) . ' invoice'
                : 'membership dues invoice',
        ];
    }

    /**
     * Assemble the email.
     *
     * Input:
     *   is_assessment   bool    an assessment-only invoice (split-assessment billing)
     *   year            int
     *   firm            string  firm name ('' = none)
     *   total           string  already formatted, e.g. "$325.00"
     *   name            string  bill-to full name
     *   first_name      string
     *   assessment_label string the assessment's name (assessment invoices)
     *   covers          string  "This invoice covers…" block ('' = none)
     *   link            string  the payment link
     *   remittance      string  the mail-a-check address ('' = none)
     *   subject_tpl / intro_tpl / closing_tpl  string  the custom wording ('' = built-in)
     *
     * @param array<string,mixed> $in
     * @return array{subject:string,body:string}
     */
    public static function build( array $in ): array {
        $isAssess = ! empty( $in['is_assessment'] );
        $year     = (int) ( $in['year'] ?? 0 );
        $firm     = (string) ( $in['firm'] ?? '' );
        $total    = (string) ( $in['total'] ?? '' );
        $name     = (string) ( $in['name'] ?? '' );
        $label    = (string) ( $in['assessment_label'] ?? '' );
        $vars     = self::vars( $in );

        $introTpl   = trim( (string) ( $in['intro_tpl'] ?? '' ) );
        $closingTpl = trim( (string) ( $in['closing_tpl'] ?? '' ) );
        $subjectTpl = trim( (string) ( $in['subject_tpl'] ?? '' ) );

        $blocks = [];
        if ( $introTpl !== '' ) {
            $blocks[] = trim( self::render( $introTpl, $vars ) );
        } else {
            $blocks[] = sprintf( 'Hi %s,', $name );
            if ( $isAssess ) {
                $blocks[] = sprintf( 'Your %d NJILGA %s invoice totals %s.', $year, $label !== '' ? $label : 'assessment', $total );
            } else {
                $blocks[] = sprintf( '%s %d NJILGA membership dues invoice totals %s.', $firm !== '' ? $firm . "'s" : 'Your', $year, $total );
            }
        }
        $reminder = self::reminder_notice( $in );
        if ( $reminder !== '' ) {
            $blocks[] = $reminder;
        }
        $updated = self::updated_notice( $in );
        if ( $updated !== '' ) {
            $blocks[] = $updated;
        }
        $covers = (string) ( $in['covers'] ?? '' );
        if ( $covers !== '' ) {
            $blocks[] = $covers;
        }
        $blocks[] = self::PAY_LINE . (string) ( $in['link'] ?? '' );
        $remittance = trim( (string) ( $in['remittance'] ?? '' ) );
        if ( $remittance !== '' ) {
            $blocks[] = 'Pay online at the link above, or mail a check to: ' . $remittance;
        }
        $blocks[] = $closingTpl !== '' ? trim( self::render( $closingTpl, $vars ) ) : "Thank you,\nNJILGA";

        $subject = '';
        if ( $subjectTpl !== '' ) {
            // One line, whatever a merge value (a firm name) contains: a newline in a subject is a header-injection vector.
            $subject = trim( (string) preg_replace( '/\s+/', ' ', self::render( $subjectTpl, $vars ) ) );
        }
        if ( $subject === '' ) {
            $subject = $isAssess
                ? sprintf( '%d NJILGA %s Invoice', $year, $label !== '' ? $label : 'Assessment' )
                : sprintf( '%d NJILGA Membership Dues Invoice%s', $year, $firm !== '' ? ' — ' . $firm : '' );
        }

        return [ 'subject' => self::marked_subject( $subject, $in ), 'body' => implode( "\n\n", $blocks ) ];
    }

    // -------------------------------------------------------------------------
    // The HTML version
    // -------------------------------------------------------------------------

    /**
     * Staff's plain wording as email HTML — escaped first, so nothing they
     * type can become markup, then a little light formatting:
     *   a blank line         → a new paragraph
     *   a line "- text"      → a bullet (consecutive ones form one list)
     *   **text**             → bold
     *   http(s)://…          → a link
     *   any other line break → a line break
     */
    public static function text_to_html( string $text ): string {
        $text = str_replace( [ "\r\n", "\r" ], "\n", trim( $text ) );
        if ( $text === '' ) {
            return '';
        }
        $pStyle  = 'margin:0 0 16px 0;font-size:16px;line-height:1.6;color:' . self::COLOR_TEXT . ';';
        $ulStyle = 'margin:0 0 16px 0;padding-left:24px;font-size:16px;line-height:1.6;color:' . self::COLOR_TEXT . ';';
        $out     = '';
        foreach ( preg_split( '/\n\s*\n/', $text ) as $block ) {
            $para    = [];
            $bullets = [];
            foreach ( explode( "\n", trim( $block ) ) as $line ) {
                if ( preg_match( '/^\s*[-•*]\s+(.*)$/u', $line, $m ) ) {
                    if ( $para ) {
                        $out .= '<p style="' . $pStyle . '">' . implode( '<br>', $para ) . '</p>';
                        $para = [];
                    }
                    $bullets[] = '<li style="margin:0 0 6px 0;">' . self::inline_html( $m[1] ) . '</li>';
                } else {
                    if ( $bullets ) {
                        $out .= '<ul style="' . $ulStyle . '">' . implode( '', $bullets ) . '</ul>';
                        $bullets = [];
                    }
                    $para[] = self::inline_html( $line );
                }
            }
            if ( $para ) {
                $out .= '<p style="' . $pStyle . '">' . implode( '<br>', $para ) . '</p>';
            }
            if ( $bullets ) {
                $out .= '<ul style="' . $ulStyle . '">' . implode( '', $bullets ) . '</ul>';
            }
        }
        return $out;
    }

    /** One line of staff wording: escaped, then **bold** and links. */
    private static function inline_html( string $line ): string {
        $h = htmlspecialchars( trim( $line ), ENT_QUOTES, 'UTF-8' );
        $h = (string) preg_replace( '/\*\*(.+?)\*\*/u', '<strong>$1</strong>', $h );
        // Already escaped, so a URL's own "&" is "&amp;" — and any other entity
        // (a quote around the URL) ends it. Trailing punctuation stays text.
        return (string) preg_replace_callback(
            '#\bhttps?://(?:[^\s<&]|&amp;)+#i',
            static function ( array $m ): string {
                $url  = rtrim( $m[0], '.,;:!?)' );
                $tail = (string) substr( $m[0], strlen( $url ) );
                return '<a href="' . $url . '" style="color:' . self::COLOR_ACCENT . ';text-decoration:underline;">' . $url . '</a>' . $tail;
            },
            $h
        );
    }

    /**
     * The HTML email — the same content as build()'s plain text, laid out
     * the way NJILGA's dues emails look: header image, heading, the opening,
     * an invoice summary card, a "Pay My Dues Online" button, the
     * mail-a-check address and the sign-off.
     *
     * Email HTML, so tables and inline styles only (mail apps ignore
     * <style> blocks and modern CSS); 600px wide, readable on a phone.
     *
     * Input — build()'s, plus:
     *   rows            array<int,array{name:string,item:string,amount:string}>  the invoice's lines
     *   covers_note     string  "Paying this invoice marks everyone listed above as current for 2027."
     *   invoice_number  string  '' = none yet
     *   due_date        string  already formatted ('' = none)
     *   logo_url        string  the header image, shown the full width of the email ('' = the site name in text instead)
     *   site_name / site_url  string
     *   heading_tpl / button_tpl  string  custom wording ('' = built-in)
     *   banner          string  a TEST / SAMPLE notice shown above everything ('' = none)
     *
     * @param array<string,mixed> $in
     */
    public static function build_html( array $in ): string {
        $e        = static function ( $v ): string { return htmlspecialchars( (string) $v, ENT_QUOTES, 'UTF-8' ); };
        $isAssess = ! empty( $in['is_assessment'] );
        $year     = (int) ( $in['year'] ?? 0 );
        $firm     = trim( (string) ( $in['firm'] ?? '' ) );
        $label    = trim( (string) ( $in['assessment_label'] ?? '' ) );
        $name     = (string) ( $in['name'] ?? '' );
        $total    = (string) ( $in['total'] ?? '' );
        $link     = (string) ( $in['link'] ?? '' );
        $vars     = self::vars( $in );
        $site     = trim( (string) ( $in['site_name'] ?? '' ) );
        $siteUrl  = (string) ( $in['site_url'] ?? '' );

        // Heading and button: custom wording, else the built-in.
        $heading = trim( (string) preg_replace( '/\s+/', ' ', self::render( trim( (string) ( $in['heading_tpl'] ?? '' ) ), $vars ) ) );
        if ( $heading === '' ) {
            $heading = $isAssess
                ? sprintf( 'NJILGA %s – Action Required', $label !== '' ? $label : 'Assessment' )
                : self::default_template( 'heading' );
        }
        $button = trim( (string) preg_replace( '/\s+/', ' ', self::render( trim( (string) ( $in['button_tpl'] ?? '' ) ), $vars ) ) );
        if ( $button === '' ) {
            $button = $isAssess ? 'Pay Online' : self::default_template( 'button' );
        }

        // The opening: the custom one, else the built-in words build() uses.
        $introTpl = trim( (string) ( $in['intro_tpl'] ?? '' ) );
        if ( $introTpl !== '' ) {
            $intro = self::render( $introTpl, $vars );
        } else {
            $intro = sprintf( 'Hi %s,', $name ) . "\n\n" . ( $isAssess
                ? sprintf( 'Your %d NJILGA %s invoice totals %s.', $year, $label !== '' ? $label : 'assessment', $total )
                : sprintf( '%s %d NJILGA membership dues invoice totals %s.', $firm !== '' ? $firm . "'s" : 'Your', $year, $total ) );
        }
        $closingTpl = trim( (string) ( $in['closing_tpl'] ?? '' ) );
        $closing    = $closingTpl !== '' ? self::render( $closingTpl, $vars ) : "Thank you,\nNJILGA";

        $font  = "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;";
        $muted = 'color:' . self::COLOR_MUTED . ';';
        $h     = '';

        $h .= '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="x-apple-disable-message-reformatting"><title>' . $e( $heading ) . '</title></head>';
        $h .= '<body style="margin:0;padding:0;background:#f4f4f5;' . $font . '">';
        // Preheader: the line mail apps show beside the subject.
        $updated  = self::updated_parts( $in );
        $reminder = self::reminder_parts( $in );
        $marker   = $reminder !== null ? self::REMINDER_PREFIX : ( $updated !== null ? self::UPDATED_PREFIX : '' );
        $h .= '<div style="display:none;max-height:0;overflow:hidden;opacity:0;">' . $e( sprintf( '%s%s %d invoice: %s', $marker, $firm !== '' ? $firm : 'Your', $year, $total ) ) . '</div>';
        $h .= '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f4f5;"><tr><td align="center" style="padding:24px 12px;">';
        $h .= '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:8px;">';

        $banner = trim( (string) ( $in['banner'] ?? '' ) );
        if ( $banner !== '' ) {
            $h .= '<tr><td style="padding:12px 24px;background:#fef3c7;border-radius:8px 8px 0 0;font-size:14px;line-height:1.5;color:#92400e;' . $font . '">' . nl2br( $e( $banner ) ) . '</td></tr>';
        }

        // Header image, the full width of the email (or the site's name in text).
        $logo = (string) ( $in['logo_url'] ?? '' );
        if ( $logo !== '' ) {
            $corner = $banner !== '' ? '0' : '8px 8px 0 0'; // square under a TEST banner
            $h     .= '<tr><td align="center" style="padding:0;">';
            $h     .= '<img src="' . $e( $logo ) . '" alt="' . $e( $site !== '' ? $site : 'NJILGA' ) . '" width="600" style="display:block;width:100%;max-width:600px;height:auto;border:0;border-radius:' . $corner . ';">';
            $h     .= '</td></tr>';
        } else {
            $h .= '<tr><td align="center" style="padding:32px 32px 8px 32px;">';
            $h .= '<div style="font-size:28px;font-weight:700;letter-spacing:1px;color:' . self::COLOR_ACCENT . ';' . $font . '">' . $e( $site !== '' ? $site : 'NJILGA' ) . '</div>';
            $h .= '</td></tr>';
        }

        // Heading.
        $h .= '<tr><td align="center" style="padding:' . ( $logo !== '' ? '28px' : '16px' ) . ' 32px 8px 32px;"><h1 style="margin:0;font-size:26px;line-height:1.3;font-weight:700;color:#111827;' . $font . '">' . $e( $heading ) . '</h1></td></tr>';

        // Opening.
        $h .= '<tr><td style="padding:24px 32px 0 32px;' . $font . '">' . self::text_to_html( $intro ) . '</td></tr>';

        // A reminder says so; an updated invoice says so, and which invoice it replaces.
        foreach ( [ $reminder, $updated ] as $notice ) {
            if ( $notice !== null ) {
                $h .= '<tr><td style="padding:0 32px 8px 32px;' . $font . '"><div style="padding:14px 16px;background:' . self::COLOR_CARD . ';border-left:4px solid ' . self::COLOR_ACCENT . ';border-radius:4px;font-size:15px;line-height:1.5;color:' . self::COLOR_TEXT . ';"><strong>' . $e( $notice['lead'] ) . '</strong> ' . $e( $notice['rest'] ) . '</div></td></tr>';
            }
        }

        // The invoice, summarised.
        $rows = (array) ( $in['rows'] ?? [] );
        $h   .= '<tr><td style="padding:8px 32px 0 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:' . self::COLOR_CARD . ';border:1px solid ' . self::COLOR_LINE . ';border-radius:8px;">';
        $h   .= '<tr><td style="padding:18px 20px 6px 20px;' . $font . '">';
        $h   .= '<div style="font-size:13px;text-transform:uppercase;letter-spacing:.06em;' . $muted . '">' . $e( $isAssess ? sprintf( '%d %s invoice', $year, $label !== '' ? $label : 'Assessment' ) : sprintf( '%d membership dues invoice', $year ) ) . '</div>';
        if ( $firm !== '' ) {
            $h .= '<div style="font-size:18px;font-weight:700;color:#111827;margin-top:4px;">' . $e( $firm ) . '</div>';
        }
        $meta = [];
        if ( (string) ( $in['invoice_number'] ?? '' ) !== '' ) {
            $meta[] = 'Invoice ' . $e( $in['invoice_number'] );
        }
        if ( (string) ( $in['due_date'] ?? '' ) !== '' ) {
            $meta[] = 'Due ' . $e( $in['due_date'] );
        }
        if ( $meta ) {
            $h .= '<div style="font-size:14px;margin-top:4px;' . $muted . '">' . implode( ' &middot; ', $meta ) . '</div>';
        }
        $h .= '</td></tr>';
        if ( $rows ) {
            $h .= '<tr><td style="padding:8px 20px 4px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="' . $font . '">';
            foreach ( $rows as $r ) {
                $who  = (string) ( $r['name'] ?? '' );
                $h   .= '<tr>';
                $h   .= '<td style="padding:8px 0;border-top:1px solid ' . self::COLOR_LINE . ';font-size:15px;line-height:1.4;color:' . self::COLOR_TEXT . ';">'
                    . ( $who !== '' ? '<strong>' . $e( $who ) . '</strong><br>' : '' )
                    . '<span style="' . $muted . 'font-size:14px;">' . $e( $r['item'] ?? '' ) . '</span></td>';
                $h   .= '<td align="right" valign="top" style="padding:8px 0 8px 12px;border-top:1px solid ' . self::COLOR_LINE . ';font-size:15px;white-space:nowrap;color:' . self::COLOR_TEXT . ';">' . $e( $r['amount'] ?? '' ) . '</td>';
                $h   .= '</tr>';
            }
            $h .= '<tr><td style="padding:12px 0;border-top:2px solid ' . self::COLOR_LINE . ';font-size:16px;font-weight:700;color:#111827;">Total</td>';
            $h .= '<td align="right" style="padding:12px 0;border-top:2px solid ' . self::COLOR_LINE . ';font-size:16px;font-weight:700;color:#111827;white-space:nowrap;">' . $e( $total ) . '</td></tr>';
            $h .= '</table></td></tr>';
        }
        $coversNote = trim( (string) ( $in['covers_note'] ?? '' ) );
        if ( $coversNote !== '' ) {
            $h .= '<tr><td style="padding:0 20px 16px 20px;font-size:14px;line-height:1.5;' . $muted . $font . '">' . $e( $coversNote ) . '</td></tr>';
        }
        $h .= '</table></td></tr>';

        // The button — "bulletproof": a coloured table cell, so it shows in Outlook too.
        $realLink = (bool) preg_match( '#^https?://#i', $link );
        $h       .= '<tr><td align="center" style="padding:28px 32px 8px 32px;">';
        if ( $realLink ) {
            $h .= '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="' . self::COLOR_ACCENT . '" style="border-radius:6px;background:' . self::COLOR_ACCENT . ';">'
                . '<a href="' . $e( $link ) . '" target="_blank" style="display:inline-block;padding:14px 28px;font-size:17px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:6px;' . $font . '">' . $e( $button ) . '</a>'
                . '</td></tr></table>';
            $h .= '<div style="margin-top:12px;font-size:13px;line-height:1.5;word-break:break-all;' . $muted . $font . '">Button not working? Open this link: <a href="' . $e( $link ) . '" style="color:' . self::COLOR_ACCENT . ';">' . $e( $link ) . '</a></div>';
        } else {
            // A preview of an invoice not created yet: no link to go to.
            $h .= '<div style="display:inline-block;padding:14px 28px;font-size:17px;font-weight:600;color:#ffffff;background:#9ca3af;border-radius:6px;' . $font . '">' . $e( $button ) . '</div>';
            $h .= '<div style="margin-top:12px;font-size:13px;' . $muted . $font . '">' . $e( $link ) . '</div>';
        }
        $h .= '</td></tr>';

        // Paying by check.
        $remittance = trim( (string) ( $in['remittance'] ?? '' ) );
        if ( $remittance !== '' ) {
            $h .= '<tr><td style="padding:20px 32px 0 32px;font-size:15px;line-height:1.6;color:' . self::COLOR_TEXT . ';' . $font . '"><strong>Prefer to pay by check?</strong> Mail it to:<br>' . nl2br( $e( $remittance ) ) . '</td></tr>';
        }

        // Sign-off.
        $h .= '<tr><td style="padding:24px 32px 32px 32px;' . $font . '">' . self::text_to_html( $closing ) . '</td></tr>';

        $h .= '</table>';
        if ( $site !== '' || $siteUrl !== '' ) {
            $h .= '<div style="max-width:600px;margin:16px auto 0 auto;font-size:12px;line-height:1.5;text-align:center;' . $muted . $font . '">'
                . $e( $site )
                . ( $siteUrl !== '' ? ( $site !== '' ? ' &middot; ' : '' ) . '<a href="' . $e( $siteUrl ) . '" style="' . $muted . '">' . $e( preg_replace( '#^https?://#', '', rtrim( $siteUrl, '/' ) ) ) . '</a>' : '' )
                . '</div>';
        }
        $h .= '</td></tr></table></body></html>';
        return $h;
    }

    // -------------------------------------------------------------------------
    // The example firm used by "Send test" and the wording preview
    // -------------------------------------------------------------------------

    /** What the firm picker calls the built-in example firm. */
    const SAMPLE_FIRM = 'sample';

    /**
     * An invoice row for a made-up firm, shaped exactly like a real one, so
     * a test email and the wording preview go through the SAME
     * MyNJILGA_Invoice_Sender::compose() a real send does — what you test is
     * what firms get. It has no payment link (compose() shows a flagged
     * placeholder for a preview) and a bill-to email that can never be a
     * real address.
     */
    public static function sample_row( int $year ): object {
        $members = [
            [ 'contact_id' => 0, 'name' => 'Ann Able', 'email' => 'ann.able@examplefirm.test', 'category' => 'professional', 'category_label' => 'Professional Membership', 'tier_label' => '1st Member', 'dues_cents' => 12500, 'assessment_cents' => 0 ],
            [ 'contact_id' => 0, 'name' => 'Bob Baker', 'email' => 'bob.baker@examplefirm.test', 'category' => 'professional', 'category_label' => 'Professional Membership', 'tier_label' => 'Members 2–5', 'dues_cents' => 7500, 'assessment_cents' => 0 ],
        ];
        $person  = [ 'contact_id' => 0, 'name' => 'Owen Owner', 'first_name' => 'Owen', 'last_name' => 'Owner', 'email' => 'owen.owner@examplefirm.test' ];
        $snap    = [
            'version' => 2, 'dues_year' => $year, 'billing_mode' => 'firm', 'invoice_kind' => 'combined',
            'company' => [ 'id' => 0, 'name' => 'Example Firm LLP' ],
            'owner' => $person, 'bill_to' => $person, 'members' => $members,
        ];
        return (object) [
            'id' => 0, 'fluentcrm_company_id' => 0, 'fluentcrm_owner_contact_id' => 0, 'bill_to_contact_id' => 0,
            'dues_year' => $year, 'invoice_kind' => 'combined', 'status' => 'draft',
            'total_amount_cents' => 20000, 'hosted_invoice_url' => '', 'roster_snapshot' => json_encode( $snap ),
        ];
    }

    /** Whether any of the three pieces has been customised. @param array<string,string> $tpl field => text */
    public static function is_custom( array $tpl ): bool {
        foreach ( array_keys( self::FIELDS ) as $field ) {
            if ( trim( (string) ( $tpl[ $field ] ?? '' ) ) !== '' ) {
                return true;
            }
        }
        return false;
    }

    /**
     * The custom wording as saved in Settings → Dues & Billing.
     *
     * @return array{subject:string,intro:string,closing:string}
     */
    public static function settings(): array {
        $out = [ 'subject' => '', 'intro' => '', 'closing' => '' ];
        foreach ( self::FIELDS as $field => $key ) {
            $out[ $field ] = trim( (string) MyNJILGA_Dues_Settings::general( $key, '' ) );
        }
        return $out;
    }
}
